// @ts-nocheck
// GENERATED by scripts/sync-shared.mjs from the web app — do not edit; run `npm run sync:shared`.
// One place that says what every stat is, how it reads in a sentence, and where its numbers come from.
// "measured" stats are computed by scripts/buildStats.mjs from the cited source; "editorial" stats are rubric
// estimates, shown as such, that players can correct by voting (see the EntityStatVote table).
import provenance from "./catalogs/provenance.json";

export type SourceId =
  | "bbref" | "pokeapi" | "worldbank" | "unesco" | "wikidata" | "wikipedia-pageviews" | "pantheon" | "superhero-api" | "editorial";

export type Source = { id: SourceId; name: string; url: string; licence: string };

