  "wikipedia-pageviews": { id: "wikipedia-pageviews", name: "Wikipedia pageviews", url: "https://pageviews.wmcloud.org", licence: "CC0" },
  pantheon: { id: "pantheon", name: "Pantheon Historical Popularity Index", url: "https://pantheon.world", licence: "CC BY-SA 4.0" },
