export type StatDef = {
  key: string;
  /** Noun, lower case: "raw power". */
  label: string;
  /** How the best item is described: "Strongest". */
  best: string;
  /** Three-letter code for tight cards. */
  code: string;
  method: "measured" | "editorial";
  source: SourceId;
  /** One line a player can read: what the number means. */
  basis: string;
};

const d = (key: string, label: string, best: string, code: string, method: StatDef["method"], source: SourceId, basis: string): StatDef => ({ key, label, best, code, method, source, basis });
const E = "editorial" as const;
const M = "measured" as const;

