export const FAMILY_OF: Record<string, keyof typeof STAT_FAMILIES> = {
  fictional: "characters", superheroes: "characters", villains: "characters", "heroes-villains": "characters", anime: "characters", videogames: "characters", disney: "characters", movies: "characters",
  pokemon: "pokemon", nba: "basketball", football: "football", films: "films", shows: "shows", food: "food", geography: "countries", flags: "flags", books: "books", music: "music", history: "history",
  weapons: "gear", gadgets: "gear", allies: "gear", vehicles: "gear", traps: "gear",
};

/** Every definition by key. Keys shared between families (power, speed, impact) keep the first, most general wording. */
const BY_KEY = new Map<string, StatDef>();
for (const defs of Object.values(STAT_FAMILIES)) for (const def of defs) if (!BY_KEY.has(def.key)) BY_KEY.set(def.key, def);

export const statDefs = (topic: string): StatDef[] => STAT_FAMILIES[FAMILY_OF[topic] ?? "characters"] ?? [];
/** The definition of a stat, as worded for a topic when the topic is known. */
export const statDef = (key: string, topic?: string): StatDef | undefined => (topic ? statDefs(topic).find((s) => s.key === key) : undefined) ?? BY_KEY.get(key);
export const statLabel = (key: string, topic?: string) => statDef(key, topic)?.label ?? key;
export const statBest = (key: string, topic?: string) => statDef(key, topic)?.best ?? key;
export const statCode = (key: string, topic?: string) => statDef(key, topic)?.code ?? key.slice(0, 3).toUpperCase();

const PROV = provenance as Record<string, Record<string, string[]>>;
/** Whether this item's number for this stat was computed from the cited source (not estimated). */
export const isMeasured = (topic: string, itemId: string, key: string) => PROV[topic]?.[itemId]?.includes(key) ?? false;

/** Sources a topic's numbers draw on, for the credits line. */
export function sourcesFor(topic: string): Source[] {
  const ids = new Set(statDefs(topic).filter((s) => s.method === "measured" || s.source !== "editorial").map((s) => s.source));
  return [...ids].map((id) => SOURCES[id]);
}
